    KafkaStartup(tokio::spawn(async move {
        let started = start_kafka_consumers(state, &cfg).await;
        if let Err(e) = &started {
            error!("Kafka consumers failed to start; shutting down: {e:#}");
            shutdown.trigger();
        }
        started
    }))
}

